arguments.new_string:
def compute_score(predict_str: str, ground_truth: str, use_boxed: bool = True, format_score: float = 0.0) -> float:
    # ``format_score`` is the weight of the format term in the blend. It is 0 so that the
    # returned reward is the accuracy itself. With a non-zero weight and a format term that
    # is constant across a prompt group, the blend only rescales every score by
    # (1 - format_score); GRPO advantages are invariant to that rescale (mean and std both
    # scale), so training was unaffected -- but every logged reward, and
    # ``val-core/.../acc``, was reported as 0.9x the true accuracy (0.5316 instead of 0.5907).
    return (1.0 - format_score) * acc_reward(predict_str, ground_truth, use_boxed) + format_score * format_reward(
        predict_str
    )

